PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    HighLimit : INT := 90;
    LowLimit : INT := 10;
    PumpTimer : TON;
END_VAR

IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

PumpTimer(IN := PumpIn AND NOT ValveOut, PT := T#5s);
PumpIn := PumpTimer.Q;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
