    prev_Level : INT := 0;
    TON_PumpIn : TON;
    TON_ValveOut : TON;
END_VAR
TON_PumpIn(IN := Level <= 10, PT := T#0s);
TON_ValveOut(IN := Level >= 90, PT := T#0s);

IF NOT TON_PumpIn.Q THEN
    PumpIn := FALSE;
ELSE
    PumpIn := TRUE;
END_IF;

IF TON_ValveOut.Q AND NOT TON_PumpIn.Q THEN
    PumpIn := FALSE;
END_IF;

IF TON_ValveOut.Q THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

prev_Level := Level;
END_PROGRAM

