PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_State : BOOL := FALSE;
    DoorB_State : BOOL := FALSE;
    T_A : TON;
    T_B : TON;
END_VAR

T_A(IN := OpenA_Cmd AND NOT DoorB_State, PT := T#0s);
T_B(IN := OpenB_Cmd AND NOT DoorA_State, PT := T#0s);

DoorA := T_A.Q OR DoorA_State;
DoorB := T_B.Q OR DoorB_State;

IF DoorA THEN
    DoorB_State := FALSE;
ELSIF DoorB THEN
    DoorA_State := FALSE;
END_IF;

END_PROGRAM

