        DoorA := FALSE;
        DoorB := TRUE;
        DoorATimer(IN := FALSE, PT := T#0s);
        DoorBTimer(IN := TRUE, PT := T#0s);
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    DoorATimer(IN := FALSE, PT := T#0s);
    DoorBTimer(IN := FALSE, PT := T#0s);
END_IF;

IF DoorATimer.Q THEN
    DoorA := TRUE;
ELSE
    DoorA := FALSE;
END_IF;

IF DoorBTimer.Q THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;
