T_A(IN := NOT OpenA_Cmd, PT := T#0s);
T_B(IN := NOT OpenB_Cmd, PT := T#0s);

IF OpenA_Cmd THEN
    IF NOT DoorB_Open THEN
        DoorA := TRUE;
        DoorB := FALSE;
        T_A(IN := TRUE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        T_A(IN := FALSE, PT := T#0s);
