ELSIF OpenB_Cmd THEN
    IF NOT DoorA_Open THEN
        DoorA := FALSE;
        DoorB := TRUE;
        T_B(IN := TRUE, PT := T#0s);
    ELSE
        DoorB := FALSE;
        T_B(IN := FALSE, PT := T#0s);
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    T_A(IN := FALSE, PT := T#0s);
    T_B(IN := FALSE, PT := T#0s);
END_IF;

DoorA := DoorA_Open AND T_A.Q;
DoorB := DoorB_Open AND T_B.Q;
END_PROGRAM

