PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

Conveyor := Running;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
ELSIF StartTimer.Q AND NOT Running THEN
    Running := TRUE;
END_IF;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    Latched : BOOL := FALSE;
    SafetyTimer : TON;
END_VAR

SafetyTimer(IN := GuardClosed OR Fault, PT := T#0s);

IF StartPB AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
END_IF;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
END_IF;

IF Running THEN
    Latched := TRUE;
    Conveyor := TRUE;
ELSE
    Conveyor := FALSE;
END_IF;

IF Not GuardClosed OR Fault THEN
    SafetyTimer(IN := TRUE, PT := T#0s);
    IF SafetyTimer.Q THEN
        Conveyor := FALSE;
        Running := FALSE;
        Latched := FALSE;
    END_IF;
END_IF;

END_PROGRAM

