    Pump : BOOL := FALSE;
    Valve : BOOL := FALSE;
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
    FillTimer : TON;
END_VAR

FillTimer(IN := NOT(EStop) AND (State = 1 OR (State = 0 AND StartCycle)), PT := T#5s);

CASE State OF
    0: // Idle
        IF NOT(EStop) AND StartCycle AND Level < 90 THEN
            State := 1;
            Pump := TRUE;
            Valve := FALSE;
        END_IF;

    1: // Filling
        IF NOT(EStop) AND Level >= 90 THEN
            State := 2;
            Pump := FALSE;
            Valve := TRUE;
        END_IF;

    2: // Draining
        IF NOT(EStop) AND Level <= 10 THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        END_IF;
END_CASE

// Safety conditions
IF NOT(EStop) AND State = 1 AND Level >= 90 THEN
    Pump := FALSE;
END_IF;

IF NOT(EStop) AND State = 2 AND Level <= 10 THEN
    Valve := FALSE;
END_IF;

IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

END_PROGRAM

