            State := 1;
            PurgeTimer(IN := TRUE);
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1: // Pre-purge
        IF PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE);
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition trial
        IF IgnitionTimer.Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

    3: // Run
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
END_CASE

// Safety conditions
IF State IN {1, 2} THEN
    IF NOT Fan THEN
        Fuel := FALSE;
    END_IF;
END_IF

IF State IN {2, 3} THEN
    IF NOT Fuel THEN
        Ignition := FALSE;
    END_IF;
END_IF

END_PROGRAM

