Pump1 := FALSE;
Pump2 := FALSE;

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    RETURN;
END_IF;

Pump1Timer(IN := Demand AND (Lead = 0), PT := T#1s);
Pump2Timer(IN := Demand AND (Lead = 1), PT := T#1s);

IF Pump1Timer.Q THEN
    Pump1 := TRUE;
    Pump2 := FALSE;
END_IF;

IF Pump2Timer.Q THEN
    Pump1 := FALSE;
    Pump2 := TRUE;
END_IF;

PrevDemand := Demand;

IF NOT PrevDemand AND Demand THEN
    Lead := 1 - Lead;
END_IF;

