    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

Pump1 := FALSE;
Pump2 := FALSE;

// Update the previous demand state for edge detection
PrevDemand := Demand;

// Check for emergency stop
IF NOT EStop THEN
    Lead := 0; // Reset lead pump on emergency stop
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Detect falling edge of demand to switch lead
    IF NOT Demand AND PrevDemand THEN
        Lead := 1 - Lead; // Toggle lead pump on falling edge of demand
    END_IF;

    // Assign pumps based on lead status and demand
    IF Demand THEN
        CASE Lead OF
            0 :
                Pump1 := TRUE;
                Pump2 := FALSE;
            1 :
                Pump1 := FALSE;
                Pump2 := TRUE;
