// Update the previous demand state
PrevDemand := Demand;

// Check for falling edge of demand
IF NOT Demand AND PrevDemand THEN
    // Toggle the lead pump
    Lead := 1 - Lead;
END_IF

// Stop both pumps if EStop is activated
IF NOT EStop THEN
    Pump1 := FALSE;
